package com.analyzercoder.application.intelligence;
import com.analyzercoder.application.llm.LlmSettingsService;import com.analyzercoder.infrastructure.persistence.mapper.IntelligenceMapper;import com.analyzercoder.infrastructure.persistence.model.KnowledgeCardRow;import com.fasterxml.jackson.core.JsonProcessingException;import com.fasterxml.jackson.databind.ObjectMapper;import java.nio.charset.StandardCharsets;import java.security.*;import java.sql.Timestamp;import java.time.Instant;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class IntelligenceService{
private static final int DIM=64;private final IntelligenceMapper mapper;private final ObjectMapper json;private final KnowledgeAttachmentService attachments;private final MarkdownRenderingService markdown;private final LlmSettingsService llm;public IntelligenceService(IntelligenceMapper mapper,ObjectMapper json,KnowledgeAttachmentService attachments,MarkdownRenderingService markdown,LlmSettingsService llm){this.mapper=mapper;this.json=json;this.attachments=attachments;this.markdown=markdown;this.llm=llm;}
@Transactional public List<SearchHit> hybridSearch(UUID repoId,String query,int limit){ensureEmbeddings(repoId);return mapper.search(repoId,query,vector(query),Math.max(1,Math.min(limit,100))).stream().map(row->new SearchHit(uuid(row,"id"),uuid(row,"snapshot_id"),string(row,"file_path"),string(row,"symbol_name"),string(row,"symbol_kind"),integer(row,"start_line"),integer(row,"end_line"),string(row,"content"),string(row,"content_hash"),number(row,"score").doubleValue(),List.of("KEYWORD","SEMANTIC"))).toList();}
@Transactional public List<Evidence> unifiedSearch(UUID repoId,String query,int limit){List<Evidence> all=new ArrayList<>();for(SearchHit hit:hybridSearch(repoId,query,6))all.add(new Evidence("CODE",hit.chunkId(),null,hit.snapshotId(),hit.symbolName()==null?hit.filePath():hit.symbolName(),hit.filePath(),hit.symbolName(),hit.symbolKind(),hit.startLine(),hit.endLine(),hit.content(),hit.contentHash(),hit.score(),hit.channels(),List.of()));ensureKnowledgeEmbeddings(repoId);for(Map<String,Object> row:mapper.searchKnowledge(repoId,query,vector(query),4)){UUID cardId=uuid(row,"id");all.add(new Evidence("KNOWLEDGE",null,cardId,null,string(row,"title"),"knowledge://"+cardId,null,string(row,"card_type"),null,null,string(row,"content"),string(row,"content_hash"),number(row,"score").doubleValue(),List.of("KNOWLEDGE","KEYWORD","SEMANTIC"),codeReferences(repoId,cardId,integer(row,"revision"))));}all.sort(Comparator.comparingDouble(Evidence::score).reversed());return all.stream().limit(Math.max(1,Math.min(limit,20))).toList();}
@Transactional public Answer ask(UUID repoId,UUID accountId,String question){List<Evidence> evidence=unifiedSearch(repoId,question,8);UUID id=UUID.randomUUID(),snapshot=evidence.stream().map(Evidence::snapshotId).filter(Objects::nonNull).findFirst().orElse(null);String answer,provider="deterministic-local";if(evidence.isEmpty())answer="当前仓库的代码索引和已发布知识中没有找到足够证据。请先完成索引、发布相关知识，或换一种更具体的描述。";else{var generated=llm.generate(llmPrompt(question,evidence));if(generated.isPresent()){answer=generated.get().answer();provider=generated.get().provider();}else{StringBuilder b=new StringBuilder("根据当前代码与团队知识，最相关的证据是：");for(int i=0;i<Math.min(5,evidence.size());i++){Evidence item=evidence.get(i);b.append("\n").append(i+1).append(". [").append(item.sourceType().equals("CODE")?"代码":"知识").append("] ").append(item.title());if(item.startLine()!=null)b.append("（第 ").append(item.startLine()).append(" 行附近）");}answer=b.append("。当前未启用外部模型，请打开证据查看原文并结合图谱验证调用关系。").toString();}}mapper.insertConversation(id,repoId,accountId,question,answer,snapshot);List<Citation> citations=new ArrayList<>();for(int i=0;i<evidence.size();i++){Evidence item=evidence.get(i);UUID cid=UUID.randomUUID();mapper.insertCitation(cid,id,item.sourceType(),item.chunkId(),item.knowledgeCardId(),item.title(),item.filePath(),item.symbolName(),item.startLine(),item.endLine(),item.contentHash(),i+1);citations.add(new Citation(cid,item.sourceType(),item.chunkId(),item.knowledgeCardId(),item.snapshotId(),item.title(),item.filePath(),item.symbolName(),item.startLine(),item.endLine(),item.content(),item.rankOr(i+1),item.codeReferences()));}return new Answer(id,answer,snapshot,citations,provider,Instant.now());}
@Transactional public GraphResult graph(UUID repoId,String symbol,int depth,String direction){rebuildGraph(repoId);int max=Math.max(1,Math.min(depth,5));List<GraphEdge> all=mapper.graphEdges(repoId).stream().map(row->new GraphEdge(string(row,"source_symbol"),string(row,"target_symbol"),string(row,"relation"))).toList();Map<String,Integer> distances=new LinkedHashMap<>();distances.put(symbol,0);List<GraphEdge> edges=new ArrayList<>();for(int d=0;d<max;d++)for(GraphEdge e:all){Integer from=distances.get(e.source()),to=distances.get(e.target());if(from!=null&&from==d&&!"UPSTREAM".equals(direction)){distances.putIfAbsent(e.target(),d+1);edges.add(e);}if(to!=null&&to==d&&!"DOWNSTREAM".equals(direction)){distances.putIfAbsent(e.source(),d+1);edges.add(e);}}List<GraphNode> nodes=distances.entrySet().stream().map(e->new GraphNode(e.getKey(),e.getValue(),e.getKey().equals(symbol))).toList();List<GraphEdge> unique=edges.stream().distinct().toList();return new GraphResult(nodes,unique,unique.size()>20?"HIGH":unique.size()>5?"MEDIUM":"LOW",List.of("静态关系不包含运行时反射与动态分派","结果绑定当前已发布快照"));}
public GraphTarget graphTarget(UUID repoId,UUID chunkId){Map<String,Object> row=mapper.findChunk(repoId,chunkId);if(row==null)throw new IllegalArgumentException("代码片段不存在");String symbol=string(row,"symbol_name");if(symbol==null||symbol.isBlank())symbol=inferSymbol(string(row,"content"),string(row,"file_path"));return new GraphTarget(symbol,string(row,"file_path"),integer(row,"start_line"));}
public List<KnowledgeCard> cards(UUID repoId,boolean includeDraft){return mapper.cards(repoId,includeDraft).stream().map(this::card).toList();}
@Transactional public KnowledgeCard createCard(UUID repoId,UUID actor,CardInput in){UUID id=UUID.randomUUID();mapper.insertCard(id,repoId,actor,in.title(),in.cardType(),in.content(),in.tags().toArray(String[]::new),in.status());KnowledgeCard card=findCard(repoId,id);attachments.attach(repoId,id,card.revision(),in.attachmentIds());attachCodeReferences(repoId,id,card.revision(),in.codeReferences());return findCard(repoId,id);}
@Transactional public KnowledgeCard updateCard(UUID repoId,UUID id,UUID actor,CardInput in){if(mapper.updateCard(id,repoId,actor,in.title(),in.cardType(),in.content(),in.tags().toArray(String[]::new),in.status())==0)throw new IllegalArgumentException("知识卡片不存在");KnowledgeCard card=findCard(repoId,id);attachments.attach(repoId,id,card.revision(),in.attachmentIds());attachCodeReferences(repoId,id,card.revision(),in.codeReferences());return findCard(repoId,id);}private KnowledgeCard findCard(UUID repoId,UUID id){return cards(repoId,true).stream().filter(card->card.id().equals(id)).findFirst().orElseThrow();}
public Map<String,String> settings(){Map<String,String> out=new LinkedHashMap<>();for(Map<String,Object> row:mapper.settings())out.put(string(row,"setting_key"),string(row,"value"));return out;}@Transactional public Map<String,String> saveSettings(UUID actor,Map<String,String> values){values.forEach((key,value)->mapper.upsertSetting(key,value,actor));return settings();}
public List<BackupView> backups(){return mapper.backups().stream().map(row->new BackupView(uuid(row,"id"),string(row,"status"),string(row,"checksum"),instant(row.get("created_at")),instant(row.get("restored_at")))).toList();}
@Transactional public BackupView createBackup(UUID actor){Map<String,Object> manifest=new LinkedHashMap<>();manifest.put("format",1);manifest.put("createdAt",Instant.now().toString());manifest.put("settings",settings());manifest.put("knowledgeCards",mapper.backupKnowledge());manifest.put("repositories",mapper.backupRepositories());manifest.put("accounts",mapper.backupAccounts());try{String payload=json.writeValueAsString(manifest),checksum=sha256(payload);UUID id=UUID.randomUUID();mapper.insertBackup(id,payload,checksum,actor);return backups().stream().filter(backup->backup.id().equals(id)).findFirst().orElseThrow();}catch(JsonProcessingException e){throw new IllegalStateException("无法生成备份清单",e);}}
@Transactional public void restoreBackup(UUID id){String payload=mapper.backupManifest(id);if(payload==null)throw new IllegalArgumentException("备份不存在或不可恢复");String expected=mapper.backupChecksum(id);if(!sha256(payload).equals(expected))throw new IllegalStateException("备份校验失败");mapper.clearSessions();mapper.markRestored(id);}
private void ensureEmbeddings(UUID repoId){for(Map<String,Object> row:mapper.missingEmbeddings(repoId))mapper.upsertEmbedding(uuid(row,"id"),repoId,vector(string(row,"content")),string(row,"content_hash"));}
private void ensureKnowledgeEmbeddings(UUID repoId){for(Map<String,Object> row:mapper.missingKnowledgeEmbeddings(repoId)){String content=string(row,"content"),hash=sha256(content);mapper.upsertKnowledgeEmbedding(uuid(row,"id"),repoId,integer(row,"revision"),vector(content),hash);}}
private void attachCodeReferences(UUID repoId,UUID cardId,int revision,List<CodeReferenceInput> refs){List<UUID> ids=(refs==null?List.<CodeReferenceInput>of():refs).stream().map(CodeReferenceInput::chunkId).filter(Objects::nonNull).distinct().limit(30).toList();int position=0;for(UUID chunkId:ids){Map<String,Object> row=mapper.findChunk(repoId,chunkId);if(row==null)throw new IllegalArgumentException("关联代码不存在或不属于当前仓库");mapper.insertCodeReference(cardId,revision,position++,repoId,uuid(row,"snapshot_id"),chunkId,string(row,"file_path"),string(row,"symbol_name"),integer(row,"start_line"),integer(row,"end_line"),string(row,"content_hash"));}}
private List<CodeReference> codeReferences(UUID repoId,UUID cardId,int revision){return mapper.codeReferences(repoId,cardId,revision).stream().map(row->new CodeReference(uuid(row,"chunk_id"),uuid(row,"snapshot_id"),string(row,"file_path"),string(row,"symbol_name"),integer(row,"start_line"),integer(row,"end_line"),string(row,"content_hash"),bool(row,"stale"))).toList();}
private void rebuildGraph(UUID repoId){mapper.deleteGraphEdges(repoId);List<Map<String,Object>> chunks=mapper.graphChunks(repoId);for(Map<String,Object> source:chunks)for(Map<String,Object> target:chunks){UUID sid=uuid(source,"id"),tid=uuid(target,"id");if(sid.equals(tid))continue;String name=string(target,"symbol_name");if(name!=null&&!name.isBlank()&&string(source,"content").contains(name+"("))mapper.insertGraphEdge(UUID.randomUUID(),repoId,uuid(source,"snapshot_id"),sid,tid,string(source,"symbol_name"),name);}}
private static String llmPrompt(String question,List<Evidence> evidence){StringBuilder prompt=new StringBuilder("你是仓库知识与代码问答助手。只能根据下面带编号的团队知识和代码证据回答，不确定时明确说明，不要编造调用关系。\\n问题：").append(question).append("\\n证据：");for(int i=0;i<evidence.size();i++){Evidence item=evidence.get(i);prompt.append("\\n[S").append(i+1).append("][").append(item.sourceType()).append("] ").append(item.title());if(item.startLine()!=null)prompt.append(":").append(item.startLine());prompt.append("\\n").append(item.content(),0,Math.min(item.content().length(),4000));if(!item.codeReferences().isEmpty())for(CodeReference ref:item.codeReferences())prompt.append("\\n关联代码：").append(ref.filePath()).append(":").append(ref.startLine());}return prompt.append("\\n请用中文回答，在事实后标注 [S编号]，并区分团队知识与源码事实；冲突时以当前快照源码为准。").toString();}
private static String inferSymbol(String content,String filePath){if(content!=null){java.util.regex.Matcher declaration=java.util.regex.Pattern.compile("(?m)\\b(?:class|interface|record|enum|function|def|func)\\s+([A-Za-z_$][\\w$]*)").matcher(content);if(declaration.find())return declaration.group(1);java.util.regex.Matcher callable=java.util.regex.Pattern.compile("(?m)\\b(?:public|protected|private|static|final|async|export)\\s+(?:[\\w<>\\[\\],.?]+\\s+)?([A-Za-z_$][\\w$]*)\\s*\\(").matcher(content);if(callable.find())return callable.group(1);}String name=filePath==null?"unknown":filePath.replace('\\','/');name=name.substring(name.lastIndexOf('/')+1);int dot=name.lastIndexOf('.');return dot>0?name.substring(0,dot):name;}
private KnowledgeCard card(KnowledgeCardRow row){return new KnowledgeCard(row.id(),row.repositoryId(),row.title(),row.cardType(),row.content(),markdown.render(row.repositoryId(),row.content()),List.of(row.tags()),row.status(),row.revision(),row.createdAt(),row.updatedAt(),attachments.list(row.repositoryId(),row.id(),row.revision()),codeReferences(row.repositoryId(),row.id(),row.revision()));}private static Object value(Map<String,Object> row,String key){Object value=row.get(key);if(value==null)value=row.get(key.toUpperCase(Locale.ROOT));return value;}private static String string(Map<String,Object> row,String key){Object value=value(row,key);return value==null?null:String.valueOf(value);}private static UUID uuid(Map<String,Object> row,String key){Object value=value(row,key);return value==null?null:value instanceof UUID id?id:UUID.fromString(value.toString());}private static Integer integer(Map<String,Object> row,String key){Object value=value(row,key);return value==null?null:((Number)value).intValue();}private static Number number(Map<String,Object> row,String key){return(Number)value(row,key);}private static boolean bool(Map<String,Object> row,String key){Object value=value(row,key);return value instanceof Boolean b?b:Boolean.parseBoolean(String.valueOf(value));}private static Instant instant(Object value){return value==null?null:value instanceof Instant i?i:((Timestamp)value).toInstant();}
private static String vector(String text){float[]out=new float[DIM];String s=text.toLowerCase(Locale.ROOT);for(int i=0;i<s.length();i++){int h=s.substring(i,Math.min(s.length(),i+3)).hashCode();out[Math.floorMod(h,DIM)]+=(h&1)==0?1:-1;}double norm=0;for(float x:out)norm+=x*x;norm=Math.sqrt(norm);StringBuilder b=new StringBuilder("[");for(int i=0;i<DIM;i++){if(i>0)b.append(',');b.append(norm==0?0:out[i]/norm);}return b.append(']').toString();}private static String sha256(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
public record SearchHit(UUID chunkId,UUID snapshotId,String filePath,String symbolName,String symbolKind,Integer startLine,Integer endLine,String content,String contentHash,double score,List<String>channels){}public record Evidence(String sourceType,UUID chunkId,UUID knowledgeCardId,UUID snapshotId,String title,String filePath,String symbolName,String symbolKind,Integer startLine,Integer endLine,String content,String contentHash,double score,List<String>channels,List<CodeReference>codeReferences){int rankOr(int fallback){return fallback;}}public record Citation(UUID id,String sourceType,UUID chunkId,UUID knowledgeCardId,UUID snapshotId,String title,String filePath,String symbolName,Integer startLine,Integer endLine,String content,int rank,List<CodeReference>codeReferences){}public record Answer(UUID conversationId,String answer,UUID snapshotId,List<Citation>citations,String provider,Instant createdAt){}public record GraphTarget(String symbol,String filePath,Integer startLine){}public record GraphNode(String symbol,int depth,boolean focus){}public record GraphEdge(String source,String target,String relation){}public record GraphResult(List<GraphNode>nodes,List<GraphEdge>edges,String risk,List<String>limitations){}public record CodeReferenceInput(UUID chunkId){}public record CodeReference(UUID chunkId,UUID snapshotId,String filePath,String symbolName,Integer startLine,Integer endLine,String contentHash,boolean stale){}public record CardInput(String title,String cardType,String content,List<String>tags,String status,List<UUID>attachmentIds,List<CodeReferenceInput>codeReferences){public CardInput{if(tags==null)tags=List.of();if(status==null)status="DRAFT";if(attachmentIds==null)attachmentIds=List.of();if(codeReferences==null)codeReferences=List.of();}}public record KnowledgeCard(UUID id,UUID repositoryId,String title,String cardType,String content,String renderedContent,List<String>tags,String status,int revision,Instant createdAt,Instant updatedAt,List<KnowledgeAttachmentService.Attachment>attachments,List<CodeReference>codeReferences){}public record BackupView(UUID id,String status,String checksum,Instant createdAt,Instant restoredAt){}
}
